local AshShovelMaker = {}
local PRODUCTS = {
    iron_ashshovel = { name = "Železni lopata za pepel", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni lopata za pepel za kovace." },
    bronze_ashshovel = { name = "Bronast lopata za pepel", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast lopata za pepel za kovace." },
    silver_ashshovel = { name = "Srebrn lopata za pepel", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn lopata za pepel za kovace." },
    gilded_ashshovel = { name = "Pozlačen lopata za pepel", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen lopata za pepel za kovace." },
    jewel_set_ashshovel = { name = "Draguljast lopata za pepel", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast lopata za pepel za kovace." },
    royal_sovereign_ashshovel = { name = "Kraljevski suveren lopata za pepel", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren lopata za pepel z biseri za krono." },
}
local BUILDINGS = {
    ashshovel_workshop = { name = "Ashshovel delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    ashshovel_house = { name = "Ashshovel hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_ashshovel_atelier = { name = "Mojstrski ashshovel atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_ashshovel_palace = { name = "Suverena ashshovel palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
AshShovelMaker.ironStock = 14; AshShovelMaker.bronzeStock = 12; AshShovelMaker.woodStock = 14; AshShovelMaker.leatherStock = 8; AshShovelMaker.silverStock = 8; AshShovelMaker.goldStock = 6; AshShovelMaker.jewelStock = 4; AshShovelMaker.pearlStock = 4
AshShovelMaker.productStock = {}; AshShovelMaker.buildings = {}; AshShovelMaker.maker = nil; AshShovelMaker.activeMaking = {}; AshShovelMaker.totalProducts = 0; AshShovelMaker.dayTimer = 0
function AshShovelMaker.init() AshShovelMaker.ironStock=14; AshShovelMaker.bronzeStock=12; AshShovelMaker.woodStock=14; AshShovelMaker.leatherStock=8; AshShovelMaker.silverStock=8; AshShovelMaker.goldStock=6; AshShovelMaker.jewelStock=4; AshShovelMaker.pearlStock=4; AshShovelMaker.productStock={}; AshShovelMaker.buildings={}; AshShovelMaker.maker=nil; AshShovelMaker.activeMaking={}; AshShovelMaker.totalProducts=0; AshShovelMaker.dayTimer=0; print("[AshShovelMaker] Royal Ash Shovel Maker System initialized (6 products, 4 buildings)") end
function AshShovelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AshShovelMaker.maker={name=n or ("Pepelar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pepelar najet: %s (spretnost: %d)",AshShovelMaker.maker.name,s),"success") end; return true end
function AshShovelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AshShovelMaker.build(id) local ok,e=AshShovelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AshShovelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AshShovelMaker.getQualityBonus() local b=0; for _,bd in ipairs(AshShovelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AshShovelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and AshShovelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and AshShovelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and AshShovelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and AshShovelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and AshShovelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AshShovelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AshShovelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AshShovelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AshShovelMaker.buildings==0 then return false,"Potrebna pepelska delavnica" end; if not AshShovelMaker.maker then return false,"Potreben pepelar" end; return true end
function AshShovelMaker.make(pt,qty) qty=qty or 1; local ok,e=AshShovelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then AshShovelMaker.ironStock=AshShovelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then AshShovelMaker.bronzeStock=AshShovelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then AshShovelMaker.woodStock=AshShovelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then AshShovelMaker.leatherStock=AshShovelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then AshShovelMaker.silverStock=AshShovelMaker.silverStock-d.silverCost*qty end; if d.goldCost then AshShovelMaker.goldStock=AshShovelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then AshShovelMaker.jewelStock=AshShovelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then AshShovelMaker.pearlStock=AshShovelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if AshShovelMaker.maker then t=math.max(1,t-math.floor(AshShovelMaker.maker.skill/13)) end; table.insert(AshShovelMaker.activeMaking,{id="ashshovel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AshShovelMaker.completeMaking(m) local q=1.0+(AshShovelMaker.getQualityBonus()/100); if AshShovelMaker.maker then q=q+(AshShovelMaker.maker.skill/140) end; q=math.min(2.5,q); AshShovelMaker.productStock[m.productType]=(AshShovelMaker.productStock[m.productType] or 0)+m.quantity; AshShovelMaker.totalProducts=AshShovelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AshShovelMaker.maker then AshShovelMaker.maker.itemsMade=AshShovelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then AshShovelMaker.maker.skill=math.min(100,AshShovelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopata izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"ashshovel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function AshShovelMaker.update(dt) if not _G.state then return end; AshShovelMaker.dayTimer=AshShovelMaker.dayTimer+dt; if AshShovelMaker.dayTimer>=30 then AshShovelMaker.dayTimer=0; for i=#AshShovelMaker.activeMaking,1,-1 do local m=AshShovelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AshShovelMaker.completeMaking(m); table.remove(AshShovelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AshShovelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AshShovelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AshShovelMaker.getStats() return {ironStock=AshShovelMaker.ironStock,bronzeStock=AshShovelMaker.bronzeStock,woodStock=AshShovelMaker.woodStock,leatherStock=AshShovelMaker.leatherStock,silverStock=AshShovelMaker.silverStock,goldStock=AshShovelMaker.goldStock,jewelStock=AshShovelMaker.jewelStock,pearlStock=AshShovelMaker.pearlStock,productStock=AshShovelMaker.productStock,numBuildings=#AshShovelMaker.buildings,hasMaker=AshShovelMaker.maker~=nil,makerName=AshShovelMaker.maker and AshShovelMaker.maker.name or "—",makerSkill=AshShovelMaker.maker and AshShovelMaker.maker.skill or 0,activeMaking=#AshShovelMaker.activeMaking,totalProducts=AshShovelMaker.totalProducts} end
return AshShovelMaker
